import{_ as o,o as r,c as t,a5 as a}from"./chunks/framework.Cooo9kuv.js";const c=JSON.parse('{"title":"WordPress 后台实用工具插件 — More Tools","description":"","frontmatter":{"标题":"WordPress 后台实用工具插件 — More Tools","日期":"2026-07-12T00:00:00.000Z","修改日期":"2026-07-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["wordpress主题插件"],"标签":["404跳转","WordPress","侧边栏优化","后台工具","安全防护","快捷菜单","管理界面","缓存清理","蜘蛛拦截"]},"headers":[{"level":2,"title":"插件简介","slug":"插件简介","link":"#插件简介","children":[]},{"level":2,"title":"功能特性","slug":"功能特性","link":"#功能特性","children":[{"level":3,"title":"访问与跳转","slug":"访问与跳转","link":"#访问与跳转","children":[]},{"level":3,"title":"后台体验","slug":"后台体验","link":"#后台体验","children":[]},{"level":3,"title":"快捷菜单","slug":"快捷菜单","link":"#快捷菜单","children":[]}]},{"level":2,"title":"使用说明","slug":"使用说明","link":"#使用说明","children":[{"level":3,"title":"第一步：安装插件","slug":"第一步-安装插件","link":"#第一步-安装插件","children":[]},{"level":3,"title":"第二步：配置功能模块","slug":"第二步-配置功能模块","link":"#第二步-配置功能模块","children":[]},{"level":3,"title":"第三步：语言切换","slug":"第三步-语言切换","link":"#第三步-语言切换","children":[]},{"level":3,"title":"AntiBot 用户升级说明","slug":"antibot-用户升级说明","link":"#antibot-用户升级说明","children":[]}]},{"level":2,"title":"注意事项","slug":"注意事项","link":"#注意事项","children":[]},{"level":2,"title":"反馈与支持","slug":"反馈与支持","link":"#反馈与支持","children":[]},{"level":2,"title":"更新日志","slug":"更新日志","link":"#更新日志","children":[{"level":3,"title":"v1.0.0（2026-07-12）","slug":"v1-0-0-2026-07-12","link":"#v1-0-0-2026-07-12","children":[]}]}],"relativePath":"md/wordpress主题插件/WordPress 后台实用工具插件 — More Tools.md","filePath":"md/wordpress主题插件/WordPress 后台实用工具插件 — More Tools.md"}'),l={name:"md/wordpress主题插件/WordPress 后台实用工具插件 — More Tools.md"};function s(n,e,i,p,d,h){return r(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="wordpress-后台实用工具插件-—-more-tools" tabindex="-1">WordPress 后台实用工具插件 — More Tools <a class="header-anchor" href="#wordpress-后台实用工具插件-—-more-tools" aria-label="Permalink to &quot;WordPress 后台实用工具插件 — More Tools&quot;">​</a></h1><blockquote><p>集成搜索蜘蛛拦截、404 跳转、后台体验增强、快捷菜单等实用功能于一体的 WordPress 后台工具集，模块化卡片式管理，中英文双语界面。</p></blockquote><p><strong>版本</strong>：v1.0.0<br><strong>适配</strong>：WordPress 5.8+<br><strong>PHP</strong>：≥ 7.2<br><strong>作者</strong>：softbangong<br><strong>授权</strong>：不限制网站数量，下载安装后永久免费使用</p><h2 id="插件简介" tabindex="-1">插件简介 <a class="header-anchor" href="#插件简介" aria-label="Permalink to &quot;插件简介&quot;">​</a></h2><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/image-24.png" alt=""></p><p>More Tools 是一款独立的后台实用工具集插件，将多个 WordPress 管理优化功能整合为一站式配置面板。插件采用模块化卡片布局，每个功能配有独立开关，支持实时展开/折叠子配置区，操作直观流畅。</p><p>插件内置中英文双语界面，支持自动、中文、English 三种语言模式切换，切换即时生效无需刷新页面。同时具备从旧版 AntiBot 插件自动迁移配置的能力，升级用户无需重新设置即可直接使用。</p><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><h3 id="访问与跳转" tabindex="-1">访问与跳转 <a class="header-anchor" href="#访问与跳转" aria-label="Permalink to &quot;访问与跳转&quot;">​</a></h3><p><strong>搜索蜘蛛拦截</strong></p><p>检测访问 <code>/wp-login.php</code>、<code>/wp-admin/</code>、<code>/xmlrpc.php</code> 路径的 User-Agent，匹配已知搜索引擎爬虫（Googlebot、Baiduspider、Bingbot、360Spider、Bytespider、YisouSpider、Petalbot、YandexBot、DuckDuckBot、Sogou、Applebot 等 20 余种）后直接返回 403 Forbidden，防止爬虫消耗服务器资源及暴露管理入口。</p><p><strong>404 跳转</strong></p><p>将网站 404（未找到）页面自动跳转至指定 URL。支持即时跳转（302）和延迟跳转（通过 meta refresh，0-30 秒可调），适用于旧链接重定向、自定义 404 页面等场景。跳转目标地址完全自定义，可指向任意合法 URL。</p><h3 id="后台体验" tabindex="-1">后台体验 <a class="header-anchor" href="#后台体验" aria-label="Permalink to &quot;后台体验&quot;">​</a></h3><p><strong>固定侧边栏菜单</strong></p><p>页面滚动时左侧管理菜单栏保持固定不动，无需回到顶部即可随时操作菜单项。响应式兼容移动端和 PC 端，不影响折叠菜单模式。</p><p><strong>侧边栏溢出滚动</strong></p><p>当后台菜单项超出屏幕高度时，侧边栏自动启用垂直滚动。同时优化 hover 子菜单交互：鼠标悬停菜单项时，子菜单以浮动层形式跟随显示在侧边栏右侧，并智能判断屏幕底部空间自动向上或向下展开，确保子菜单始终完整可见。</p><p><strong>自定义侧边栏宽度</strong></p><p>可自定义后台左侧菜单栏宽度，范围 120-300 像素（默认 160 像素）。启用后折叠菜单模式下的宽度保持 36 像素不受影响，内容区域自动适配新宽度。</p><p><strong>圆形头像</strong></p><p>将后台管理工具条和用户资料页的头像统一显示为圆形，提升视觉整洁度。</p><p><strong>隐藏仪表盘模块</strong></p><p>隐藏 WordPress 仪表盘默认模块（欢迎面板、快速草稿、活动、站点健康状态等），提供更干净的仪表盘视图。仅在仪表盘页面生效，不影响其他后台页面。</p><p><strong>返回顶部/底部按钮</strong></p><p>在所有后台页面右下角显示固定的返回顶部和前往底部按钮，可根据需要独立启用或关闭这两个按钮。支持自定义右侧距离、底部距离、按钮尺寸、按钮颜色和滚动显示阈值，满足不同使用偏好。按钮在页面滚动超过阈值后渐显，点击后平滑滚动到目标位置。</p><p><strong>一键清理缓存</strong></p><p>在顶部管理工具条添加「清理 WordPress 缓存」快捷按钮，点击即刷新 WordPress 对象缓存（Object Cache），无需进入设置页面操作。同时插件设置页也提供独立的缓存清理按钮。</p><h3 id="快捷菜单" tabindex="-1">快捷菜单 <a class="header-anchor" href="#快捷菜单" aria-label="Permalink to &quot;快捷菜单&quot;">​</a></h3><p><strong>顶部快捷菜单</strong></p><p>在管理工具条添加「快捷菜单」入口，可自定义子菜单项列表。每个菜单项按「名称|地址」格式一行一个配置，支持完整 URL 和相对路径（如 <code>/wp-admin/plugins.php</code>），插件自动补全路径。适合将常用管理页面、外部工具链接等集中收纳，提升操作效率。</p><p><strong>隐藏菜单关键词</strong></p><p>根据关键词隐藏后台左侧菜单栏和顶部工具条中的菜单项。关键词按行或竖线（|）分隔，支持多关键词组合匹配。匹配逻辑基于菜单文本内容，点击隐藏区域的菜单项仍可通过直接 URL 访问。</p><h2 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h2><h3 id="第一步-安装插件" tabindex="-1">第一步：安装插件 <a class="header-anchor" href="#第一步-安装插件" aria-label="Permalink to &quot;第一步：安装插件&quot;">​</a></h3><p>将 <code>more-tools</code> 文件夹上传至网站 <code>/wp-content/plugins/</code> 目录，进入 WordPress 后台「插件管理」页面，找到「More Tools」并点击启用。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/image-25.png" alt=""></p><h3 id="第二步-配置功能模块" tabindex="-1">第二步：配置功能模块 <a class="header-anchor" href="#第二步-配置功能模块" aria-label="Permalink to &quot;第二步：配置功能模块&quot;">​</a></h3><p>插件激活后，后台左侧菜单栏会出现「实用工具」菜单项，点击进入插件设置页面。页面按功能分为三大模块卡片：</p><p>— <strong>访问与跳转</strong>：蜘蛛拦截开关、404 跳转开关及跳转地址/延迟配置；<br> — <strong>后台体验</strong>：固定菜单、圆形头像、隐藏仪表盘、侧边栏滚动、自定义宽度、返回顶部/底部按钮、缓存清理按钮等独立开关及子配置；<br> — <strong>快捷菜单</strong>：顶部快捷菜单开关、菜单项列表、隐藏关键词列表。</p><p>每个功能配有独立 toggle 开关，开关右侧有功能说明文字。部分功能（如 404 跳转、自定义侧边栏宽度、返回顶部/底部按钮）开启后会自动展开对应的子配置区域，关闭时自动折叠。点击页面底部「保存设置」按钮统一保存所有配置。</p><h3 id="第三步-语言切换" tabindex="-1">第三步：语言切换 <a class="header-anchor" href="#第三步-语言切换" aria-label="Permalink to &quot;第三步：语言切换&quot;">​</a></h3><p>设置页面顶部工具条提供语言切换下拉菜单，支持自动（跟随站点语言）、中文、English 三种模式。切换后页面文本即时更新，不影响已保存的配置。</p><h3 id="antibot-用户升级说明" tabindex="-1">AntiBot 用户升级说明 <a class="header-anchor" href="#antibot-用户升级说明" aria-label="Permalink to &quot;AntiBot 用户升级说明&quot;">​</a></h3><p>如果您之前使用过 AntiBot 插件，More Tools 在首次激活时会自动读取并迁移 AntiBot 的配置数据，无需手动重新设置。迁移仅执行一次，后续配置互不影响。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>— 蜘蛛拦截通过 User-Agent 字符串匹配判断爬虫身份，依赖爬虫如实发送 UA，无法防御恶意伪造 UA 的请求；<br> — 404 跳转功能仅在 WordPress 正常识别为 404 页面时触发，如主题自定义 404 处理逻辑可能与插件冲突；<br> — 固定侧边栏和侧边栏滚动功能互斥，同时启用时滚动模式优先级更高；<br> — 自定义侧边栏宽度需合理设置，过小可能导致菜单文字被截断；<br> — 隐藏菜单关键词仅在后台管理页面生效，不影响前台菜单显示；<br> — 清理缓存功能调用 <code>wp_cache_flush()</code>，依赖站点使用的对象缓存实现机制。</p><h2 id="反馈与支持" tabindex="-1">反馈与支持 <a class="header-anchor" href="#反馈与支持" aria-label="Permalink to &quot;反馈与支持&quot;">​</a></h2><p>— 作者：softbangong<br> — 作者网站：softbangong.com<br> — 作者网站：softbangong.top<br> — 邮箱：<a href="mailto:softbangong@gmail.com" target="_blank" rel="noreferrer">softbangong@gmail.com</a></p><h2 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h2><h3 id="v1-0-0-2026-07-12" tabindex="-1">v1.0.0（2026-07-12） <a class="header-anchor" href="#v1-0-0-2026-07-12" aria-label="Permalink to &quot;v1.0.0（2026-07-12）&quot;">​</a></h3><p>— 首次发布；<br> — 搜索蜘蛛拦截：拦截 20 余种已知搜索引擎爬虫访问后台/登录页/xmlrpc；<br> — 404 跳转：支持即时跳转和延迟跳转，跳转地址和延迟秒数自由配置；<br> — 固定侧边栏菜单：页面滚动时左侧菜单栏保持固定；<br> — 侧边栏溢出滚动：菜单项超屏时自动启用滚动，hover 子菜单智能定位浮出；<br> — 自定义侧边栏宽度：120-300 像素范围自由调节；<br> — 圆形头像：后台头像统一圆角显示；<br> — 隐藏仪表盘模块：清理欢迎面板、快速草稿、活动等默认小组件；<br> — 返回顶部/底部按钮：右下角固定按钮，支持位置、尺寸、颜色和显示阈值自定义；<br> — 一键清理缓存：工具条快捷按钮和设置页按钮双重入口；<br> — 顶部快捷菜单：可配置的自定义链接列表，支持绝对 URL 和相对路径；<br> — 隐藏菜单关键词：按关键词匹配隐藏后台菜单项；<br> — 中英文双语界面：自动/中文/English 三种语言模式即时切换；<br> — 卡片式模块化管理界面，toggle 开关与子配置区联动展开/折叠；<br> — 支持从 AntiBot 插件自动迁移已有配置。</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/3029.html" target="_blank" rel="noreferrer">https://www.softbangong.com/3029.html</a></p>',54)])])}const b=o(l,[["render",s]]);export{c as __pageData,b as default};
